void generateMsg(uint8_t* msg, uint32_t* msgLen)
{
    static uint32_t l_msgLen = 33; // default msg len

    l_msgLen += 33;

    if ( 3300 > l_msgLen)
    {
        l_msgLen = 33;
    }

    for (int i = 0; i < l_msgLen; i++)
    {
        msg[i] = rand() % 0xFF; // generate random number between 0 to 255
    }

    *msgLen = l_msgLen;
}

void generateSignature(uint8_t* signature)
{
    for (int i = 0; i < DIL_MLDSA_87_CRYPTO_SIG_SIZE; i++)
    {
        signature[i] = rand() % 0xFF; // generate random number between 0 to 255
    }
}

int randomVectorValidate (uint32_t i_iteration, char* i_outputFile)
{
    int ret_val = 0;
    uint32_t errorCount = 0;
    uint32_t msgLen = 0;
    uint8_t msg[4000] = {0};
    uint8_t signature[DIL_MLDSA_87_CRYPTO_SIG_SIZE] = {0};

    FILE* outputFile = fopen(i_outputFile, "w");

    if (outputFile == NULL)
    {
        perror("Error opening output file\n");
        return 1; // Exit with error code
    }

    srand(time(NULL)); //use current time as seed for random generator

    printf ("\nVerifying one KAT vector before Random vector test\n");
    fprintf (outputFile, "\nVerifying one KAT vector before Random vector test\n");

    ret_val = mldsa_verify ( fixed_dil_sign, DIL_MLDSA_87_CRYPTO_SIG_SIZE,
                             fixed_sample_msg, sizeof(fixed_sample_msg),
                             fixed_public_key, DIL_MLDSA_87_CRYPTO_PUBLICKEY_SIZE);
    printf ("Result of KAT: %s\n", ret_val ? "Pass" : "Fail");

    writeVerifyParamToOutputFile(outputFile, 0, fixed_sample_msg, sizeof(fixed_sample_msg), fixed_public_key,
                                 fixed_dil_sign, ret_val);

    printf ("\n\nStarted generating RANDOM message and signature...\n");
    fprintf (outputFile, "\n\nStarted generating RANDOM message and signature...\n");

    for (int i = 0 ; i < i_iteration; i++)
    {
        generateMsg(msg, &msgLen);
        generateSignature(signature);

        if ( (ret_val = mldsa_verify ( signature, DIL_MLDSA_87_CRYPTO_SIG_SIZE,
                                       msg, msgLen,
                                       fixed_public_key, DIL_MLDSA_87_CRYPTO_PUBLICKEY_SIZE)) <= 0)
        {
            errorCount++;
        }

        writeVerifyParamToOutputFile(outputFile, i, msg, msgLen, fixed_public_key, signature, ret_val);
    }

    printf ("\n\nNumber fo iteration: %d, Number of Error : %d error\n\n", i_iteration, errorCount);
    fprintf (outputFile, "\n\nNumber fo iteration: %d, Number of Error : %d error\n\n", i_iteration, errorCount);

    // Close both the input and output files
    fclose(outputFile);


    if (i_iteration != errorCount)
    {
        return errorCount;
    }

    return 0;
}


